export function worldArt(level,completed=[],last=null,cover=false){
 const p=palettes[level.theme]||palettes.pond,night=level.theme==='night',sunny=completed.includes('晴'),n=completed.length;
 return `<svg viewBox="0 0 900 430" preserveAspectRatio="xMidYMid ${cover?'slice':'meet'}" role="img" aria-label="${esc(level.title)}，已完成 ${n} 个小任务"><rect width="900" height="430" fill="${p[0]}"/><circle cx="740" cy="66" r="${night?30:35}" fill="${night?'#e5dbab':sunny?'#efcf83':'#e5dbb1'}"/>${night?'<circle cx="756" cy="55" r="28" fill="#263f50"/>':''}<path d="M-40 239 140 40 334 222 515 74 719 222 841 105 960 257Z" fill="${p[1]}" opacity=".6"/><path d="M-40 272 80 162 246 265 414 128 599 268 774 157 960 275Z" fill="${p[2]}" opacity=".35"/><path d="M0 291Q160 259 330 291T630 285 900 282V430H0Z" fill="${night?'#607d74':'#cbd8b9'}"/><path d="M-25 388Q156 346 305 376T614 354 925 360" fill="none" stroke="${p[3]}" stroke-width="56"/><path d="M-20 324Q138 297 307 329T610 310 922 318" fill="none" stroke="${night?'#b5bb91':'#ece6c9'}" stroke-width="32"/><path d="M70 326q74-10 122 0m173-4q80 14 148 2m150-7q80-13 139 1" fill="none" stroke="#c0c5a1" stroke-width="2" stroke-dasharray="5 7"/>${tree(48,256,.66)}${tree(862,257,.62)}${level.quests.map((q,i)=>{const done=completed.includes(q.char);return `<g data-world-mission="${i}" transform="translate(${[181,450,719][i]} 202)"><g class="${last===q.char?'g-world-done':''}">${object(level.effects?.[i]||q.effect||effectFor(q.char),done)}<rect x="-62" y="59" width="124" height="30" rx="14" fill="${done?'#eaf0d7':'#edf0df'}" fill-opacity=".9"/><text class="g-world-tag" y="80" text-anchor="middle">${esc(done?q.after:q.before)}</text>${done?'<circle cx="55" cy="60" r="10" fill="#94a775"/><path d="m51 60 3 3 5-7" fill="none" stroke="#f8f3d7" stroke-width="2"/>':''}</g></g>`;}).join('')}${fox(106+n*215,328,1.05)}${n?flower(283,357)+flower(539,342,'#d5b880'):''}${n>1?'<g fill="#d3ba70"><path d="M330 114q-16-20-19-7-1 11 19 12 18-13 9-19-7-4-9 14"/><path d="M588 96q-16-20-19-7-1 11 19 12 18-13 9-19-7-4-9 14"/></g>':''}${n===3?'<g fill="#e9db9d" class="g-twinkle"><circle cx="239" cy="105" r="3"/><circle cx="616" cy="131" r="3"/><circle cx="384" cy="82" r="3"/></g>':''}</svg>`;
}
// Kept separate from SVG text so all quest labels remain plain, escaped text.
let effects=new Map();
export function registerArtGlyphs(glyphs){effects=new Map(glyphs.map(g=>[g.char,g.effect]));}
const effectFor=char=>effects.get(char)||'spark';
